  return alias;
}

function getShortUrlByAlias(alias) {
  return db.prepare('SELECT * FROM short_urls WHERE alias = ?').get(alias);
}

function isExpired(row) {
  return row.expires_at && new Date(row.expires_at).getTime() < Date.now();
}

