4	// --- Interfaces ---
5	
6	export interface TokenUsage {
7	  inputTokens: number;
8	  outputTokens: number;
9	  cacheCreationTokens: number;
10	  cacheReadTokens: number;
11	  totalTokens: number;
12	}
13	
14	/** Per-token USD rates for one OpenRouter model slug (GET /api/v1/models `pricing`). */
15	export interface ModelPricing {
16	  prompt: number;
17	  completion: number;
18	  input_cache_read: number;
19	  input_cache_write: number;
20	}
21	
22	export type PricingTable = Record<string, ModelPricing>;
23	
24	export type CostSource = 'openrouter_ledger' | 'tokens_x_live_pricing';
25	
26	export interface CostResult {
27	  costUsd: number;
28	  costSource: CostSource;
29	}
30	
31	// --- Transcript Token Parsing ---
32	
33	/**
34	 * Parses a transcript.jsonl file and sums token usage across all assistant entries.
35	 *
36	 * Each JSONL line may contain:
37	 * {"type":"assistant","message":{"usage":{"input_tokens":N,"output_tokens":N,"cache_creation_input_tokens":N,"cache_read_input_tokens":N}}}
38	 */
39	export async function parseTranscriptTokens(
40	  transcriptPath: string,
41	): Promise<TokenUsage | null> {
42	  let content: string;
43	  try {
44	    content = await readFile(transcriptPath, 'utf-8');
45	  } catch (error) {
46	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
47	      return null;
48	    }
49	    throw new Error(
50	      `Failed to parse transcript at ${transcriptPath}: ${error instanceof Error ? error.message : String(error)}`,
51	    );
52	  }
53	
54	  const lines = content.split('\n').filter((line) => line.trim().length > 0);
55	
56	  let inputTokens = 0;
57	  let outputTokens = 0;
58	  let cacheCreationTokens = 0;
59	  let cacheReadTokens = 0;
60	
61	  for (const line of lines) {
62	    let parsed: unknown;
63	    try {
64	      parsed = JSON.parse(line);
65	    } catch {
66	      // Skip malformed lines
67	      continue;
68	    }
69	
70	    if (
71	      typeof parsed !== 'object' ||
72	      parsed === null ||
73	      (parsed as Record<string, unknown>).type !== 'assistant'
74	    ) {
75	      continue;
76	    }
77	
78	    const message = (parsed as Record<string, unknown>).message;
79	    if (typeof message !== 'object' || message === null) {
80	      continue;
81	    }
82	
83	    const usage = (message as Record<string, unknown>).usage;
84	    if (typeof usage !== 'object' || usage === null) {
85	      continue;
86	    }
87	
88	    const u = usage as Record<string, unknown>;
89	    inputTokens += typeof u.input_tokens === 'number' ? u.input_tokens : 0;
90	    outputTokens += typeof u.output_tokens === 'number' ? u.output_tokens : 0;
91	    cacheCreationTokens +=
92	      typeof u.cache_creation_input_tokens === 'number'
93	        ? u.cache_creation_input_tokens
94	        : 0;
95	    cacheReadTokens +=
96	      typeof u.cache_read_input_tokens === 'number'
97	        ? u.cache_read_input_tokens
98	        : 0;
99	  }
100	
101	  const totalTokens =
102	    inputTokens + outputTokens + cacheCreationTokens + cacheReadTokens;
103	
104	  // If we found no usage at all, return null
105	  if (totalTokens === 0) {
106	    return null;
107	  }
108	
109	  return {
110	    inputTokens,
111	    outputTokens,
112	    cacheCreationTokens,
113	    cacheReadTokens,
114	    totalTokens,
115	  };
116	}
117	
118	// --- Live Pricing (GET /api/v1/models -- public, no key required) ---
119	
120	const OPENROUTER_MODELS_URL = 'https://openrouter.ai/api/v1/models';
121	const MODELS_SNAPSHOT_FILENAME = 'models-snapshot.json';
122	
123	interface OpenRouterModelEntry {
124	  id?: string;
125	  pricing?: {
126	    prompt?: string;
127	    completion?: string;
128	    input_cache_read?: string;
129	    input_cache_write?: string;
130	  };
131	}
132	
133	/**
134	 * Fetches live per-token pricing for every OpenRouter model and indexes it
135	 * by slug. Public endpoint (Phase 0 table) -- no API key required.
136	 */
137	export async function fetchPricing(): Promise<PricingTable> {
138	  const response = await fetch(OPENROUTER_MODELS_URL);
139	  if (!response.ok) {
140	    throw new Error(
141	      `Failed to fetch OpenRouter model pricing: HTTP ${response.status}`,
142	    );
143	  }
144	
145	  const body = (await response.json()) as { data?: OpenRouterModelEntry[] };
146	  const table: PricingTable = {};
147	  for (const model of body.data ?? []) {
148	    if (!model.id || !model.pricing) continue;
149	    table[model.id] = {
150	      prompt: Number(model.pricing.prompt ?? 0),
151	      completion: Number(model.pricing.completion ?? 0),
152	      input_cache_read: Number(model.pricing.input_cache_read ?? 0),
153	      input_cache_write: Number(model.pricing.input_cache_write ?? 0),
154	    };
155	  }
156	  return table;
157	}
158	
159	/**
160	 * Fetches live pricing and snapshots the raw table to
161	 * `<resultsDir>/models-snapshot.json` for reproducibility.
162	 */
163	export async function snapshotPricing(resultsDir: string): Promise<PricingTable> {
164	  const table = await fetchPricing();
165	  await mkdir(resultsDir, { recursive: true });
166	  await writeFile(
167	    join(resultsDir, MODELS_SNAPSHOT_FILENAME),
168	    JSON.stringify(table, null, 2),
169	  );
170	  return table;
171	}
172	
173	/**
174	 * Reuses a previously-written `models-snapshot.json` when present -- keeps a
175	 * report reproducible across re-runs and lets fixture/test runs inject
176	 * pricing without hitting the network. Fetches live (and snapshots) only
177	 * when no cached file exists yet.
178	 */
179	export async function loadOrFetchPricing(resultsDir: string): Promise<PricingTable> {
180	  try {
181	    const cached = await readFile(
182	      join(resultsDir, MODELS_SNAPSHOT_FILENAME),
183	      'utf-8',
184	    );
185	    return JSON.parse(cached) as PricingTable;
186	  } catch (error) {
187	    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
188	  }
189	  return snapshotPricing(resultsDir);
190	}
