192	/**
193	 * Looks up per-token rates for a slug, tolerating OpenRouter's
194	 * served-vs-requested slug mismatch (Phase 4 smoke findings): a concrete
195	 * dated variant such as `anthropic/claude-4.6-opus-20260205` never appears
196	 * in `/models`, which only lists the requested alias
197	 * (`anthropic/claude-opus-4.6`). `priceTokens` is always called with the
198	 * *requested* slug (`aggregateAgent`'s `modelVersion`), so this rarely
199	 * bites in practice, but stripping a trailing `-YYYYMMDD` suffix is a
200	 * cheap, harmless safety net against a future caller passing a served slug.
201	 */
202	function resolveRates(slug: string, pricing: PricingTable): ModelPricing | undefined {
203	  if (pricing[slug]) return pricing[slug];
204	  const stripped = slug.replace(/-\d{8}$/, '');
205	  if (stripped !== slug && pricing[stripped]) return pricing[stripped];
206	  return undefined;
